"""Fixed stripping loopback proxy: actual HTTP and WebSocket tunnel, no fake Grafana."""
import http.client,http.server,select,socket,threading,urllib.parse
class PrefixProxy:
 def __init__(self):self.backend_port=None
 def __enter__(self):
  owner=self
  class Handler(http.server.BaseHTTPRequestHandler):
   protocol_version='HTTP/1.1'
   def do_GET(self):self.forward()
   def do_POST(self):self.forward()
   def forward(self):
    if not self.path.startswith('/grafana/'):
     self.send_response(404);self.send_header('Content-Length','0');self.end_headers();return
    length=int(self.headers.get('Content-Length','0'));body=self.rfile.read(length)
    upgrade=self.headers.get('Upgrade','').lower()=='websocket'
    with socket.create_connection(('127.0.0.1',owner.backend_port),timeout=5) as upstream:
     headers={k:v for k,v in self.headers.items() if k.lower() not in ('connection','content-length')}
     headers['Connection']='Upgrade' if upgrade else 'close';headers['Content-Length']=str(len(body))
     request=(self.command+' /'+self.path[len('/grafana/'):]+' HTTP/1.1\r\n'+
       ''.join(k+': '+v+'\r\n' for k,v in headers.items())+'\r\n').encode()+body
     upstream.sendall(request)
     if upgrade:
      while True:
       ready,_,_=select.select([upstream,self.connection],[],[],5)
       if not ready:break
       closed=False
       for peer in ready:
        chunk=peer.recv(65536)
        if not chunk:closed=True;break
        (self.connection if peer is upstream else upstream).sendall(chunk)
       if closed:break
     else:
      while True:
       chunk=upstream.recv(65536)
       if not chunk:break
       self.connection.sendall(chunk)
    self.close_connection=True
   def log_message(self,*args):pass
  self.server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);self.server.daemon_threads=True
  self.port=self.server.server_port;self.origin='http://127.0.0.1:'+str(self.port);self.url=self.origin+'/grafana/'
  self.thread=threading.Thread(target=self.server.serve_forever,daemon=True);self.thread.start();return self
 def request(self,method,path,body=None,headers=None):
  connection=http.client.HTTPConnection('127.0.0.1',self.port,timeout=6)
  try:
   connection.request(method,path,body=body,headers=headers or {})
   response=connection.getresponse();return response.status,response.getheaders(),response.read()
  finally:connection.close()
 def __exit__(self,*args):self.server.shutdown();self.server.server_close();self.thread.join(2)
